<?php
declare(strict_types=1);require_once __DIR__.'/config/database.php'; require_once __DIR__.'/config/ui.php';$pdo=srnu_db();$id=(int)($_GET['id']??$_POST['id']??0);$c=srnu_obtener_cotizacion($id);if(!$c){http_response_code(404);exit('No encontrada');}
$uploadDir=__DIR__.'/uploads/recepciones';if(!is_dir($uploadDir))@mkdir($uploadDir,0775,true);
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['eliminar_foto'])){$fid=(int)$_POST['foto_id'];$st=$pdo->prepare('SELECT archivo FROM recepcion_fotos WHERE id=? AND cotizacion_id=?');$st->execute([$fid,$id]);$f=$st->fetch();if($f){$path=__DIR__.'/'.$f['archivo'];if(is_file($path))@unlink($path);$pdo->prepare('DELETE FROM recepcion_fotos WHERE id=? AND cotizacion_id=?')->execute([$fid,$id]);}header('Location: recepcion.php?id='.$id);exit;}
 $firmaData=trim((string)($_POST['firma_data']??''));
 $vals=[$id,trim($_POST['kilometraje']??''),trim($_POST['combustible']??''),trim($_POST['placas']??''),trim($_POST['danos']??''),trim($_POST['testigos']??''),trim($_POST['objetos']??''),trim($_POST['notas']??''),trim($_POST['firma_cliente']??''),$firmaData];
 $pdo->prepare('INSERT INTO recepciones(cotizacion_id,kilometraje,combustible,placas,danos,testigos,objetos,notas,firma_cliente,firma_data) VALUES(?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE kilometraje=VALUES(kilometraje),combustible=VALUES(combustible),placas=VALUES(placas),danos=VALUES(danos),testigos=VALUES(testigos),objetos=VALUES(objetos),notas=VALUES(notas),firma_cliente=VALUES(firma_cliente),firma_data=IF(VALUES(firma_data)<>\'\',VALUES(firma_data),firma_data),updated_at=NOW()')->execute($vals);
 if(!empty($_FILES['fotos']['name']) && is_array($_FILES['fotos']['name'])){foreach($_FILES['fotos']['name'] as $i=>$name){if($_FILES['fotos']['error'][$i]!==UPLOAD_ERR_OK||$_FILES['fotos']['size'][$i]>8*1024*1024)continue;$tmp=$_FILES['fotos']['tmp_name'][$i];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)continue;$fname='recepcion_'.$id.'_'.bin2hex(random_bytes(6)).'.'.$ext;$dest=$uploadDir.'/'.$fname;if(move_uploaded_file($tmp,$dest)){$rel='uploads/recepciones/'.$fname;$pdo->prepare('INSERT INTO recepcion_fotos(cotizacion_id,archivo) VALUES(?,?)')->execute([$id,$rel]);}}}
 $pdo->prepare("UPDATE cotizaciones SET estado='Vehículo recibido',updated_at=NOW() WHERE id=? AND estado IN ('Cotización','Aprobada','Anticipo recibido')")->execute([$id]);
 // Crear o actualizar expediente permanente del vehículo.
 $vc=$pdo->prepare('SELECT vehiculo_id,cliente,telefono,vehiculo FROM cotizaciones WHERE id=?');$vc->execute([$id]);$vv=$vc->fetch();
 if($vv){$vid=(int)($vv['vehiculo_id']??0);if($vid>0){$pdo->prepare('UPDATE vehiculos SET cliente=?,telefono=?,descripcion=?,placas=?,kilometraje=?,updated_at=NOW() WHERE id=?')->execute([$vv['cliente'],$vv['telefono'],$vv['vehiculo'],trim($_POST['placas']??''),trim($_POST['kilometraje']??''),$vid]);}else{$pdo->prepare('INSERT INTO vehiculos(cliente,telefono,descripcion,placas,kilometraje) VALUES(?,?,?,?,?)')->execute([$vv['cliente'],$vv['telefono'],$vv['vehiculo'],trim($_POST['placas']??''),trim($_POST['kilometraje']??'')]);$vid=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE cotizaciones SET vehiculo_id=? WHERE id=?')->execute([$vid,$id]);}}
 header('Location: recepcion.php?id='.$id);exit;
}
$st=$pdo->prepare('SELECT * FROM recepciones WHERE cotizacion_id=?');$st->execute([$id]);$r=$st->fetch()?:[];$st=$pdo->prepare('SELECT * FROM recepcion_fotos WHERE cotizacion_id=? ORDER BY id');$st->execute([$id]);$fotos=$st->fetchAll();function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recepción · <?=h($c['folio'])?></title><link rel="icon" href="favicon.png"><style>body{font-family:Arial;background:#f4f5f7}.w{max-width:950px;margin:30px auto;padding:0 15px}.p{background:#fff;padding:18px;border-radius:10px}a,.btn{background:#111;color:#fff;padding:8px 11px;border-radius:7px;text-decoration:none;border:0;cursor:pointer}.g{display:grid;grid-template-columns:1fr 1fr;gap:10px}.g input,.g textarea{width:100%;padding:9px;border:1px solid #ccc;border-radius:6px;box-sizing:border-box}.full{grid-column:1/-1}.photos{display:flex;gap:10px;flex-wrap:wrap}.photo{width:160px}.photo img{width:160px;height:110px;object-fit:cover;border-radius:8px;border:1px solid #ddd}canvas{width:100%;max-width:600px;height:180px;border:1px solid #bbb;border-radius:8px;touch-action:none;background:#fff}@media(max-width:650px){.g{grid-template-columns:1fr}.full{grid-column:auto}}</style><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><?php srnu_appbar('cotizaciones'); ?><div class="w"><a href="cotizaciones.php">← Cotizaciones</a> <a href="orden_trabajo.php?id=<?=$id?>">Orden</a><h1>Recepción del vehículo</h1><div class="p"><p><?=h($c['cliente'])?> · <b><?=h($c['vehiculo'])?></b></p><form method="post" enctype="multipart/form-data" class="g" id="recepcion-form"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="firma_data" id="firma-data"><label>Kilometraje<input name="kilometraje" value="<?=h($r['kilometraje']??'')?>"></label><label>Combustible<input name="combustible" placeholder="Ej. 1/2 tanque" value="<?=h($r['combustible']??'')?>"></label><label>Placas<input name="placas" value="<?=h($r['placas']??'')?>"></label><label>Nombre del cliente que firma<input name="firma_cliente" value="<?=h($r['firma_cliente']??'')?>"></label><label class="full">Daños existentes<textarea name="danos"><?=h($r['danos']??'')?></textarea></label><label class="full">Testigos encendidos<textarea name="testigos"><?=h($r['testigos']??'')?></textarea></label><label class="full">Objetos dentro del vehículo<textarea name="objetos"><?=h($r['objetos']??'')?></textarea></label><label class="full">Notas<textarea name="notas"><?=h($r['notas']??'')?></textarea></label><label class="full">Fotografías de recepción (JPG/PNG/WebP, hasta 8 MB c/u)<input type="file" name="fotos[]" multiple accept="image/jpeg,image/png,image/webp"></label><div class="full"><b>Firma del cliente</b><br><canvas id="firma" width="600" height="180"></canvas><br><button type="button" class="btn" id="limpiar-firma">Limpiar firma</button><?php if(!empty($r['firma_data'])):?><span> · Ya hay una firma guardada; solo se reemplaza si firmas nuevamente.</span><?php endif;?></div><button class="btn">Guardar recepción</button></form></div><?php if($fotos):?><div class="p" style="margin-top:12px"><h3>Fotografías</h3><div class="photos"><?php foreach($fotos as $f):?><div class="photo"><a href="foto.php?id=<?=(int)$f['id']?>" target="_blank"><img src="foto.php?id=<?=(int)$f['id']?>"></a><form method="post" onsubmit="return confirm('¿Eliminar foto?')"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="foto_id" value="<?=(int)$f['id']?>"><button name="eliminar_foto">Eliminar</button></form></div><?php endforeach;?></div></div><?php endif;?></div><script>
(()=>{const c=document.getElementById('firma'),ctx=c.getContext('2d'),hidden=document.getElementById('firma-data');let draw=false,changed=false;ctx.lineWidth=2;ctx.lineCap='round';function pos(e){const r=c.getBoundingClientRect(),t=e.touches?e.touches[0]:e;return{x:(t.clientX-r.left)*(c.width/r.width),y:(t.clientY-r.top)*(c.height/r.height)}}function start(e){draw=true;changed=true;const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);e.preventDefault()}function move(e){if(!draw)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();e.preventDefault()}function stop(){draw=false}['mousedown','touchstart'].forEach(x=>c.addEventListener(x,start));['mousemove','touchmove'].forEach(x=>c.addEventListener(x,move));['mouseup','mouseleave','touchend'].forEach(x=>c.addEventListener(x,stop));document.getElementById('limpiar-firma').onclick=()=>{ctx.clearRect(0,0,c.width,c.height);changed=false;hidden.value=''};document.getElementById('recepcion-form').addEventListener('submit',()=>{if(changed)hidden.value=c.toDataURL('image/png')})})();
</script></body></html>
